export interface AuditLogEntry {
  id: string;
  timestamp: string;
  type: 'trade' | 'system' | 'compliance' | 'security' | 'configuration' | 'data-access' | 'api-call' | 'user-action';
  severity: 'critical' | 'high' | 'medium' | 'low' | 'info';
  entity: string;
  action: string;
  user: string;
  details: string;
  outcome: 'success' | 'failure' | 'warning' | 'blocked';
  ipAddress: string;
  affectedSystems: string[];
}

function pad(n: number, w = 3): string { return String(n).padStart(w, '0'); }
function iso(d: number, h: number, m: number, s: number): string { const dt = new Date(); dt.setDate(dt.getDate() - d); dt.setHours(h, m, s, 0); return dt.toISOString(); }

